// Generated by esquadro: do not edit. Running a resource's actions, the same
// in its list, on a record's page and in its queue: asking first (confirm, or
// the fields of ask), copying text, changing fields (patch, with If-Match)
// or your own run, and saying how it went.
import { useQueryClient } from "@tanstack/react-query"
import { useId, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Field, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Spinner } from "@/components/ui/spinner"
import { api } from "../api.ts"
import { ask as confirm } from "./confirm.tsx"
import { copy } from "./copy.tsx"
import { describe, fieldErrors, fieldMessage } from "./errors.ts"
import { FieldInput } from "./form.tsx"
import { t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import type { Action, Resource } from "./resource.ts"
import { toast } from "./toast.tsx"

/** Whether an action may run on a record: its when, and, to change it, the record's update. */
export function allowed(a: Action, r: Rec): boolean {
  if (a.when && !a.when(r)) return false
  if (a.patch && !(r.can ?? []).includes("update")) return false
  return true
}

/** The keys of a resource's actions: a key given to two is said, once, in development. */
export function actionKeys(resource: Resource): Map<string, Action> {
  const out = new Map<string, Action>()
  for (const a of resource.actions ?? []) {
    if (!a.key) continue
    if (out.has(a.key) && import.meta.env.DEV) {
      console.error(`${resource.meta.name}: the key ${a.key} is given to "${out.get(a.key)!.label}" and "${a.label}"`)
      continue
    }
    out.set(a.key, a)
  }
  return out
}

/** What a patch sends: the action's fields, then those asked for. */
export function patchOf(a: Action, record: Rec, asked: Record<string, unknown> = {}): Record<string, unknown> {
  const fixed = typeof a.patch === "function" ? a.patch(record) : (a.patch ?? {})
  return { ...fixed, ...asked }
}

/**
 * Runs an action on a record, asking nothing: copy, patch (If-Match), run.
 * The bulk actions of a list run so, on each record.
 */
export async function applyAction(meta: ResourceMeta, a: Action, r: Rec, asked: Record<string, unknown> = {}): Promise<void> {
  if (a.copy) {
    await copy(a.copy(r))
  }
  if (a.patch) {
    await meta.api(api as never).patch(r.id, patchOf(a, r, asked), { ifMatch: r })
  }
  if (a.run) {
    await a.run(r)
  }
}

/** Whether an action runs on several records at once: bulk, asking and copying nothing. */
export function bulk(a: Action): boolean {
  return Boolean(a.bulk) && !a.ask?.length && !a.copy
}

interface Asking {
  action: Action
  record: Rec
  done: (ok: boolean) => void
}

/**
 * The actions of a resource, to run on its records: perform runs one and
 * answers whether it did; dialog is to be rendered once, for the fields an
 * action asks for.
 */
export function useActions(resource: Resource) {
  const { meta } = resource
  const queryClient = useQueryClient()
  const [asking, setAsking] = useState<Asking | null>(null)

  const apply = (a: Action, r: Rec, asked: Record<string, unknown>) => applyAction(meta, a, r, asked)

  const perform = async (a: Action, r: Rec): Promise<boolean> => {
    if (!allowed(a, r)) return false
    if (a.confirm && !(await confirm(a.confirm, { destructive: a.destructive }))) return false
    if (a.ask && a.ask.length > 0) {
      return new Promise<boolean>((done) => setAsking({ action: a, record: r, done }))
    }
    try {
      await apply(a, r, {})
      // A copy says so itself.
      if (a.patch || a.run) toast(t("done"))
      return true
    } catch (e) {
      toast(describe(e), "error")
      return false
    } finally {
      queryClient.invalidateQueries({ queryKey: [meta.name] })
    }
  }

  const dialog = asking && (
    <AskDialog
      action={asking.action}
      record={asking.record}
      submit={async (values) => {
        await apply(asking.action, asking.record, values)
        toast(t("done"))
        queryClient.invalidateQueries({ queryKey: [meta.name] })
      }}
      close={(ok) => {
        asking.done(ok)
        setAsking(null)
      }}
    />
  )
  return { perform, dialog }
}

/** The fields an action asks for before it runs, in a small dialog. */
function AskDialog({
  action,
  record,
  submit,
  close,
}: {
  action: Action
  record: Rec
  submit: (values: Record<string, unknown>) => Promise<void>
  close: (ok: boolean) => void
}) {
  const fields = action.ask ?? []
  const [values, setValues] = useState<Record<string, unknown>>(() => Object.fromEntries(fields.map((f) => [f.name, record[f.name] ?? ""])))
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [busy, setBusy] = useState(false)
  const formId = useId()
  const closed = useRef(false)
  const finish = (ok: boolean) => {
    if (closed.current) return
    closed.current = true
    close(ok)
  }
  const send = async () => {
    const missing: Record<string, string> = {}
    for (const f of fields) {
      const v = values[f.name]
      if (f.required && f.kind !== "bool" && (v === null || v === undefined || v === "")) missing[f.name] = "required"
    }
    if (Object.keys(missing).length > 0) return setErrors(missing)
    setBusy(true)
    try {
      // What is empty goes as null: it empties what may be empty.
      await submit(Object.fromEntries(Object.entries(values).map(([k, v]) => [k, v === "" ? null : v])))
      finish(true)
    } catch (e) {
      const refused = fieldErrors(e)
      if (Object.keys(refused).length > 0) setErrors(refused)
      else toast(describe(e), "error")
    } finally {
      setBusy(false)
    }
  }
  return (
    <Dialog open onOpenChange={(o) => !o && finish(false)}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {action.icon && <action.icon className="size-5" />} {action.label}
          </DialogTitle>
        </DialogHeader>
        <form
          id={formId}
          onSubmit={(e) => {
            e.preventDefault()
            send()
          }}
        >
          <FieldGroup className="gap-5">
            {fields.map((f: FieldMeta) => (
              <Field key={f.name} data-invalid={errors[f.name] !== undefined || undefined}>
                <FieldLabel htmlFor={`field-${f.name}`} className="font-semibold text-muted-foreground">
                  {f.label}
                  {f.required && f.kind !== "bool" && <span className="text-destructive">*</span>}
                </FieldLabel>
                <FieldInput
                  field={f}
                  value={values[f.name]}
                  invalid={errors[f.name] !== undefined}
                  onChange={(v) => {
                    setErrors(({ [f.name]: _, ...rest }) => rest)
                    setValues((all) => ({ ...all, [f.name]: v }))
                  }}
                />
                {errors[f.name] && <FieldError>{fieldMessage(f, errors[f.name])}</FieldError>}
              </Field>
            ))}
          </FieldGroup>
        </form>
        <DialogFooter>
          <Button type="button" variant="ghost" onClick={() => finish(false)} disabled={busy}>
            {t("cancel")}
          </Button>
          <Button type="submit" form={formId} disabled={busy}>
            {busy && <Spinner />}
            {action.label}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
